local UIWorldBossLockNode = Class('UIWorldBossLockNode')

function UIWorldBossLockNode:__init()
    self._curBossPlanVo = nil
end

function UIWorldBossLockNode:__delete()
    self._curBossPlanVo = nil
end

function UIWorldBossLockNode:Awake()
    SetButtonAction(self.BtnCheck, function()
        local t = worldBossComponent:GetLastWeekRankInfo()
        if t then
            local comp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
            local playerDojo = comp:GetPlayerDojo()
            local meRankData = {
                rankNum = 0,
                hurt = 0,
            }
            for k, v in pairs(t) do
                if checkNumber(v.playerId) == checkNumber(playerDojo.playerId) then
                    meRankData.rankNum = v.rankNum
                    meRankData.hurt = v.score
                end
            end

            CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UIWorldBossPlayerRankingsDialog, parameters = {data = t, rankMeData = meRankData}}, {
                {id = Constants.UITypeIds.UIWorldBossMainDialog}
            })
        end
    end)
end

function UIWorldBossLockNode:Refresh(bossPlanVo)
    if not bossPlanVo then
        return
    end
    self._curBossPlanVo = bossPlanVo        --当前bossVo
    --self:FillLastWeekRank()
end

--绘制排名信息
function UIWorldBossLockNode:FillLastWeekRank()
    local info = worldBossComponent:GetLastWeekRankInfo()
    if not info then
        return
    end

    for k, v in pairs(info) do
        local go = self["RankNode"..k]
        if go then
            KTool.SetActive(go, true)
            local scr = CfUtils.GetLuaScr(go, UIWorldBossPlayerRankNode)       
            if scr then
                v.rankNum = checkNumber(k)
                scr:Refresh(v, false, Vector3(0.25, 0.25, 0.25))
            end 
        end
    end
end

function UIWorldBossLockNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIWorldBossLockNode
